    C c;
    constructor(C _c) { c = _c; }

    // single public test that demonstrates the invariant
    // Parameters:
    //  _initialMin - value to set before initialization
    //  _newMin - value attempted to set after initialization
    function run(uint _initialMin, uint _newMin) public {
        // set MinSum once before initialization
        c.SetMinSum(_initialMin);
        // mark contract initialized
        c.Initialized();

        // Now attempt to change MinSum again. In original (P) this should revert.
        // We capture whether it reverts by calling it inside a try/catch on the low-level call.
        // Use address(c).call to detect revert boolean while obeying rules: it's an external interaction observed via revert boolean.
        (bool success, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", _newMin));

        // The distinguishing property: after initialization, SetMinSum must not succeed.
        // On P success == false; on mutant M success == true (since it allows overwriting).
        assert(!success);
    }

    // allow receiving ETH in case tests supply value (not used here but harmless)
    receive() external payable {}
}

