contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: set MinSum, initialize, then call SetMinSum again
    // Inputs: initial MinSum value to set, arbitrary caller address is msg.sender of this contract
    function run(uint initialVal) public {
        // precondition: this contract must be allowed to call c.SetMinSum before initialization
        // call SetMinSum first to set a known value
        c.SetMinSum(initialVal);
        // record MinSum after first set
        uint before = c.MinSum();
        // mark contract initialized so further SetMinSum should revert on original but in mutant it won't set same value
        c.Initialized();
        // Attempt to call SetMinSum again with a different argument; in original this will revert and leave MinSum unchanged
