        // In original contract: second SetMinSum call reverts (ok == false) and MinSum remains equal to before.
        // In mutant: second call succeeds (ok == true) and sets MinSum to uint(uint160(msg.sender)) which will differ from before.
        assert((ok == false && after == before) || (ok == true && after == before));
    }

    // receive to accept ETH if needed by tests (not used here)
    receive() external payable {}
