import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the value to set; the property: if Initialized() was called, then any SetMinSum call should revert and leave MinSum unchanged
    function testFuzz_property(uint256 newMin) public {
        // keep wide domain
        // 1) initialize contract
        c.Initialized();

        // read old value
        uint256 before = c.MinSum();

        // call SetMinSum and catch revert to observe whether call succeeded from caller POV
        bool ok;
        try c.SetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a call to SetMinSum when contract is initialized, the reference implementation must always revert (ok == false)
        // and therefore MinSum must remain unchanged. The mutant that assigns before the guard can lead to MinSum being changed
        // despite the external call reverting in some contexts; we assert that either the call succeeded and MinSum equals newMin,
        // or the call failed and MinSum stayed equal to before. This captures the invariant that a revert-visible failure
        // does not change the observable MinSum.
        uint256 after = c.MinSum();

        // single assertion: if call reverted (ok==false) then MinSum must be unchanged
        assertTrue(!(ok == false && after != before));
