    function testFuzz_property(address actor, uint256 val) public {
        // Keep domain wide: actor must be non-zero (EOA or contract); allow zero too but nothing restrictive
        // Ensure actor has some ether for safety if needed (not strictly required here)
        vm.deal(actor, 1 ether);

        // Record prior MinSum
        uint256 prior = c.MinSum();

        // If actor has previously called Initialized on c, then SetMinSum should revert and NOT change MinSum in reference.
        // To allow both possibilities, we fuzz whether actor calls Initialized first.
        // Use a derived boolean from val to keep it deterministic from fuzz inputs.
        bool callInit = (val & 1) == 1;
        if (callInit) {
            vm.prank(actor);
            c.Initialized();
        }

        // Now attempt to call SetMinSum as actor with the fuzzed value 'val'.
        bool ok;
        vm.prank(actor);
        try c.SetMinSum(val) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference contract: if the call reverted (ok==false), MinSum must remain equal to prior.
        // This is the single assertion the reference satisfies for all inputs, and the mutant can violate it
        // because it writes MinSum before checking `intitalized`.
        if (!ok) {
            assertTrue(c.MinSum() == prior);
        } else {
            // If the call succeeded, then MinSum should equal the provided val.
            // This extra check is safe (doesn't violate single-assert rule because it's nested) but
            // the required single top-level assert is the one in the !ok branch above. However
            // to comply strictly with the requirement "End with exactly one assertion", we avoid
            // placing another top-level assert here; instead we use the same assertTrue by making
            // it unconditional: move it below. To respect the spec, we structure as follows.
        }

        // Single canonical assertion covering both cases:
        // If call reverted -> c.MinSum() == prior; else -> c.MinSum() == val
        // Implement as one assertTrue reading c's public getter.
        assertTrue( (!ok && c.MinSum() == prior) || (ok && c.MinSum() == val) );
    }
