import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: actor address, initialUnlock (previous unlockTime), sent value, lockTime
    function testFuzz_property(address actor, uint256 initialUnlock, uint256 sendVal, uint256 lockTime) public {
        vm.assume(actor != address(0));
        // keep values in wide but reasonable bounds to avoid overflow in timestamp math for the test environment
        lockTime = bound(lockTime, 0, 1 days);
        sendVal = bound(sendVal, 0, 1 ether);
        // arrange: set up actor's Holder by calling Put once to establish balance and unlockTime = block.timestamp + initOffset
        // we cannot directly set acc.unlockTime, so simulate by advancing time and calling Put with a chosen _lockTime
        // compute a desired previous unlockTime by doing an initial Put with an offset offsetInit such that resulting unlockTime == initialUnlock
        // To achieve a prior unlockTime value, we'll warp the block.timestamp to a baseTime and choose firstLock = initialUnlock - baseTime if initialUnlock >= baseTime
        uint256 baseTime = block.timestamp;
        // If initialUnlock < baseTime, we simulate a previous smaller unlockTime by first putting with zero lock so unlockTime stays 0 or prior; that'll cover < baseTime cases.
        // We'll perform initialPutLock such that resulting unlockTime equals initialUnlock when possible.
        uint256 initialPutLock = 0;
        if (initialUnlock >= baseTime) {
            uint256 delta = initialUnlock - baseTime;
            // bound delta to avoid huge value
            if (delta > 1 days) delta = 1 days;
            initialPutLock = delta;
        } else {
            initialPutLock = 0;
        }

        // fund actor and perform initial Put to set up acc.unlockTime
        vm.deal(actor, sendVal + 1 ether);
        vm.prank(actor);
        c.Put{value: sendVal}(initialPutLock);

        // record previous unlockTime via public getter Acc(actor).unlockTime is accessible through autogenerated getter
        (uint256 prevUnlockTime, uint256 prevBalance) = getHolder(actor);

        // now perform the decisive Put with fuzzed lockTime and value
        // make sure actor has funds
        vm.deal(actor, sendVal + 1 ether);
        vm.prank(actor);
        bool ok;
        try c.Put{value: sendVal}(lockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        // After reference Put, the rule is: newUnlockTime == (block.timestamp + lockTime) if that is greater than prevUnlockTime, else prevUnlockTime.
        // Read actual stored unlockTime and assert that property holds (this is the single assertion). The mutant that does acc.unlockTime += _lockTime can violate this for some inputs.
        (uint256 newUnlockTime, uint256 newBalance) = getHolder(actor);

        uint256 expected = prevUnlockTime;
        uint256 candidate = block.timestamp + lockTime;
        if (candidate > prevUnlockTime) expected = candidate;

        assertTrue(newUnlockTime == expected);
    }

    // helper to read the Holder struct via the public mapping getter signature
    function getHolder(address a) internal view returns (uint256 unlockTime, uint256 balance) {
        // the compiler generates Acc(address) -> (uint,uint)
        (unlockTime, balance) = c.Acc(a);
    }
}

