import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: actor address, previousLock (to create a prior unlockTime), lockAdd (the new _lockTime), and deposit
    function testFuzz_property(address actor, uint256 previousLock, uint256 lockAdd, uint256 deposit) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // keep deposit within reasonable bounds and non-zero so we actually pay
        deposit = bound(deposit, 1, 1 ether);
        // keep lock values in a wide but bounded range to avoid overflow in timestamp math
        previousLock = bound(previousLock, 0, 10 days);
        lockAdd = bound(lockAdd, 0, 10 days);

        // Step 1: initialize a prior state for actor by calling Put once with previousLock
        vm.deal(actor, deposit);
        vm.prank(actor);
        c.Put{value: deposit}(previousLock);

        // Read previous unlockTime via the public mapping getter: Acc(actor).unlockTime is not directly accessible,
        // but Acc is public, so the auto getter returns (uint unlockTime, uint balance) when called.
        (uint prevUnlockTime, uint prevBalance) = c.Acc(actor);

        // Advance time a bit to allow block.timestamp to move beyond prevUnlockTime in some cases
        // Warp forward by up to 1 day to create cases where prevUnlockTime < block.timestamp
        vm.warp(block.timestamp + 1 days);

        // Ensure actor has funds to send again
        vm.deal(actor, deposit);
        vm.prank(actor);
        c.Put{value: deposit}(lockAdd);

        // Now check the invariant: new unlockTime == max(prevUnlockTime, block.timestamp_at_second_put + lockAdd)
        (uint newUnlockTime, uint newBalance) = c.Acc(actor);

        // Compute expected: note block.timestamp now is at the time after the second Put call returned;
        // but because we called c.Put inside vm.prank without further warps, the block.timestamp used
        // inside Put equals the current block.timestamp. We reconstruct expected as the max.
        uint expectedCandidate = block.timestamp + lockAdd;
        uint expected = prevUnlockTime > expectedCandidate ? prevUnlockTime : expectedCandidate;

        // Single assertion reading c's public getter-derived state. The correct reference satisfies this for all inputs;
        // the mutant that does acc.unlockTime += _lockTime will fail for some inputs (e.g., when prevUnlockTime < block.timestamp,
        // it will set newUnlockTime = prevUnlockTime + lockAdd which can be < expectedCandidate).
        assertTrue(newUnlockTime == expected);
    }
}

